-- V21: ИИ-советник на лендинге (S45) — контент рецептов.
--
-- Рецепты — редакционный контент, а не генерация модели: блок «рекомендованные
-- рецепты» на витрине должен быть детерминированным и не hallucinate состав.
-- Ингредиенты привязаны к SKU каталога (`ingredients[].sku`), поэтому советник
-- советует только тем, что реально продаётся; битый/удалённый SKU просто не
-- показывается в карточке.
--
-- steps / ingredients / tags хранятся JSON-текстом: Hibernate валидирует схему
-- (ddl-auto=validate), а разбор делает RecipeContentParser — составной тип в БД
-- не нужен, рецептов единицы.

CREATE TABLE recipes (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    slug            TEXT        NOT NULL UNIQUE,
    title           TEXT        NOT NULL,
    summary         TEXT        NOT NULL,
    steps           TEXT        NOT NULL DEFAULT '[]',
    ingredients     TEXT        NOT NULL DEFAULT '[]',
    cooking_minutes INTEGER,
    difficulty      TEXT,
    tags            TEXT        NOT NULL DEFAULT '[]',
    sort_order      INTEGER     NOT NULL DEFAULT 100,
    is_active       BOOLEAN     NOT NULL DEFAULT TRUE,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX recipes_active_sort_idx ON recipes (is_active, sort_order);

INSERT INTO recipes (slug, title, summary, steps, ingredients, cooking_minutes, difficulty, tags, sort_order) VALUES
  ('steyk-ribay-na-grile', 'Стейк рибай на гриле', 'Классическая прожарка рибая: толстая соль, высокий нагрев, отдых перед нарезкой. Порция 250 г.', $json$["Солить стейк за 40 минут до жарки — соль вытягивает сок, но мясо отдыхает и не теряет его обратно.","Разогреть гриль до 250 °C, зону жира смазать тонким слоем подсолнечного масла.","Прогреть стейк по 3–4 минуты с каждой стороны до температуры в центре 52 °C (medium rare).","Дать отдохнуть 5–7 минут под фольгой, затем нарезать поперёк волокон."]$json$, $json$[{"name":"Стейк рибай","sku":"steyk-ribay","quantity":"250 г на порцию"}]$json$, 25, 'Средняя', $json$["гриль","стейк","говядина","жарение"]$json$, 10),

  ('steyk-na-kosti-v-dukhovke', 'Стейк на кости в духовке', 'Запекание для зала с низкой температурой: кость даёт навар, соус получается сам.', $json$["Разогреть духовку до 180 °C.","Посолить стейк, поперчить, добавить чеснок и веточку розмарина.","Запекать 18–22 минуты до внутренней температуры 56 °C, ориентируясь на толщину.","Выдержать 5 минут, подавать с соком, выделившимся при запекании."]$json$, $json$[{"name":"Стейк на кости","sku":"steyk-na-kosti","quantity":"300 г на порцию"}]$json$, 35, 'Лёгкая', $json$["запекание","стейк","говядина","без надзора"]$json$, 20),

  ('svinaya-vyrezka-karbonara', 'Свиная вырезка карбонара', 'Панировка, яйцо и пармезан дают хрустящий слой; внутри — сочная нежная свинина.', $json$["Нарезать вырезку порциями 150 г и отбить до толщины 8–10 мм.","Посолить, поперчить, сбрызнуть оливковым маслом.","Обвалять в муке, затем в взбитом яйце, затем в смеси пармезана и панировочных сухарей.","Обжарить на сковороде по 3 минуты с каждой стороны до золотистой корочки.","Довести в духовке при 170 °C 8 минут и подавать сразу."]$json$, $json$[{"name":"Вырезка свиная","sku":"vyrezka-svinaya","quantity":"150 г на порцию"},{"name":"Яйца куриные С0","sku":"yaytsa-kurinye-s0","quantity":"1 шт на порцию"}]$json$, 30, 'Средняя', $json$["свинина","хрустящее","обжаривание"]$json$, 30),

  ('kurenaya-bedro-s-travami', 'Куриное бедро с травами', 'Бедро без кости маринуется и запекается до золотистой корочки — стабильная подача в зале.', $json$["Замариновать бедро в масле с тимьяном, чесноком и цедрой лимона на 2 часа.","Выложить на решётку кожицей вверх, чтобы она подрумянилась.","Запекать при 190 °C 25–30 минут до золотистой корочки.","Выдержать 5 минут и подавать с долькой лимона."]$json$, $json$[{"name":"Бедро куриное","sku":"bedro-kurinoye","quantity":"180 г на порцию"}]$json$, 45, 'Лёгкая', $json$["курица","запекание","гриль","быстро"]$json$, 40),

  ('kolbaski-na-grile', 'Колбаски на гриле с луком', 'Классика гриля: колбаски прокалываются, чтобы сок не вытекал, и подаются с карамелизированным луком.', $json$["Проколоть колбаски вилкой в 4–5 местах — иначе сок вытечет на решётку.","Уложить на решётку под 45° и жарить 12–15 минут, переворачивая до румяной корочки.","Параллельно карамелизировать лук на сковороде до золотистого цвета.","Проверить готовность: сок внутри прозрачный, температура 71 °C."]$json$, $json$[{"name":"Колбаски для жарки","sku":"kolbaski-dlya-zharki","quantity":"150 г на порцию"}]$json$, 25, 'Лёгкая', $json$["гриль","колбаски","быстро"]$json$, 50),

  ('frikadeli-iz-kurinyogo-farsha', 'Фрикадельки из куриного фарша', 'Сочные фрикадельки без добавок: лук, хлеб и яйцо дают нужную структуру.', $json$["Смешать фарш с мелко рубленым луком, размоченным хлебом, яйцом и солью. Не перетирать массу.","Охладить 20 минут в холодильнике, чтобы фарш застыл.","Сформовать фрикадельки по 70 г и обвалять в панировке.","Обжарить на сковороде по 4 минуты, довести в духовке при 180 °C 10 минут."]$json$, $json$[{"name":"Фарш куриный","sku":"farsh-kuriniy","quantity":"350 г на 5 фрикаделек"},{"name":"Яйца куриные С0","sku":"yaytsa-kurinye-s0","quantity":"1 шт"}]$json$, 40, 'Средняя', $json$["фарш","курица","закуски"]$json$, 60),

  ('kottlety-iz-govyazhiego-farsha', 'Котлеты из говяжьего фарша', 'Плотные котлеты для бургеров и комбинированных заказов: без сухости, но с текстурой.', $json$["Смешать фарш с панировочными сухарями, молоком, луком и солью.","Выдержать массу 15 минут, чтобы сухари набухли.","Сформовать котлеты по 120 г.","Обжарить на сильном огне по 4 минуты, довести в духовке при 180 °C 12 минут."]$json$, $json$[{"name":"Фарш говяжий","sku":"farsh-govyazhiy","quantity":"120 г на котлету"}]$json$, 35, 'Лёгкая', $json$["фарш","говядина","обжаривание","быстро"]$json$, 70),

  ('cheeseburger-patty', 'Чизбургер-патти из говяжьего фарша', 'Тонкий патти под давлением — сок держится, патти остаётся сочным после жарки.', $json$["Взять охлаждённый фарш и сформовать лепёшку чуть шире булки, не утрамбовывая.","Сделать углубление лопаткой в центре, чтобы патти не выгибался.","Жарить на сильном огне 3–4 минуты, не переворачивая до появления корки.","Довести в духовке при 180 °C 8 минут — готовность 71 °C в центре."]$json$, $json$[{"name":"Фарш говяжий","sku":"farsh-govyazhiy","quantity":"150 г на бургер"}]$json$, 20, 'Лёгкая', $json$["фарш","говядина","бургер","быстро"]$json$, 80),

  ('pashtet-iz-farsha-s-yaytsom', 'Паштет из фарша с яйцом', 'Закусочный паштет на вынос и в стеклянной таре: запекается в форме, охлаждается и режется.', $json$["Обжарить лук и морковь до мягкости, остудить.","Смешать с фаршем, сыром и яйцом, пробить блендером до гладкости.","Выложить в форму и запекать при 160 °C 45 минут до плотной текстуры.","Остудить в холодильнике минимум 4 часа, подавать ломтиками с хлебом."]$json$, $json$[{"name":"Фарш говяжий","sku":"farsh-govyazhiy","quantity":"400 г"},{"name":"Яйца куриные С0","sku":"yaytsa-kurinye-s0","quantity":"2 шт"}]$json$, 70, 'Средняя', $json$["фарш","закуски","яйца","готовится заранее"]$json$, 90),

  ('omlet-s-farshem', 'Омлет с фаршем и зеленью', 'Скоростная подача для завтраков и бизнес-ланчей: 10 минут от старта до тарелки.', $json$["Обжарить фарш с зеленью до полной готовности, отложить.","Взбить яйца с солью и молоком, вылить на разогретую сковороду.","На половину омлета выложить фарш, довести под крышкой 2–3 минуты.","Сложить пополам и подавать сразу — омлет лучше всего в первые минуты."]$json$, $json$[{"name":"Яйца куриные С0","sku":"yaytsa-kurinye-s0","quantity":"3 шт на порцию"},{"name":"Фарш куриный","sku":"farsh-kuriniy","quantity":"100 г на порцию"}]$json$, 12, 'Лёгкая', $json$["яйца","фарш","курица","завтрак","быстро"]$json$, 100)
ON CONFLICT (slug) DO NOTHING;
